function archiveIcon(key){return '<svg class="enemy-art" viewBox="0 0 64 64" aria-hidden="true"><path d="'+ARCHIVE_PATHS[key]+'" fill="currentColor" fill-opacity=".12" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/></svg>';}
function archiveFoe(key,r=S.run){const [name,hp]=ARCHIVE_FOES[key];r.archiveSerial=(r.archiveSerial||0)+1;return Object.assign(enemy(name,archiveIcon(key),hp,0),{act2:true,act5:true,act5Kind:key,archiveId:'archive-'+r.archiveSerial,actionStep:0,reading:false,healGrowth:0,str:0});}
function archiveEncounter(r,type){if(type==='boss')return [archiveFoe('boss',r)];if(type==='elite'){r.archiveElites??=[];if(!r.archiveElites.length)r.archiveElites=shuffle(['sage','twins','keeper']);const key=r.archiveElites.pop();return (key==='twins'?['white','black']:[key]).map(k=>archiveFoe(k,r));}r.archiveFights=(r.archiveFights||0)+1;const candidates=BALANCE_NORMAL_5[r.archiveFights===1?'early':'late'];return (typeof balanceEncounterPick==='function'?balanceEncounterPick(5,candidates):rand(candidates)).map(entry=>{const [key,offset]=entry.split('@');return archiveFoe(key,r);});}
function archiveBag(r){r.archiveSummonBag??=[];while(r.archiveSummonBag.length<2){const batch=shuffle([...ARCHIVE_NORMAL]);if(r.archiveSummonBag.length&&batch[0]===r.archiveSummonBag.at(-1))[batch[0],batch[1]]=[batch[1],batch[0]];r.archiveSummonBag.push(...batch);}return r.archiveSummonBag;}
function clearArchiveReading(e){if(e?.act5)e.reading=false;}
function archiveAction(r,e){const a={...ARCHIVE_FOES[e.act5Kind][2][e.actionStep%ARCHIVE_FOES[e.act5Kind][2].length],wasReading:!!e.reading};if(a.readingHits)a.h=e.reading?a.readingHits:1;if(a.readingStrength)a.s=e.reading?a.readingStrength:0;if(a.growHeal)a.heal+=(e.healGrowth||0);if(a.summon){const bag=archiveBag(r),space=Math.max(0,2-r.enemies.filter(x=>x.hp>0&&x.summonerId===e.archiveId).length);a.count=Math.min(e.reading?2:1,space);a.candidates=bag.slice(0,2);a.extraStrength=e.reading?2:0;a.extraBlock=e.reading?10:0;}if(a.support){const eligible=r.enemies.filter(x=>x!==e&&x.hp>0);if(!eligible.some(x=>x.archiveId===e.supportTargetId))e.supportTargetId=rand(eligible)?.archiveId||null;a.supportTarget=e.supportTargetId;}return a;}
function planArchive(r){for(const e of r.enemies||[]){if(!e.act5||e.hp<=0)continue;if(e.act5Kind==='boss')archiveBag(r);const a=archiveAction(r,e);e.snowAction=a;e.intent=e.hunterStun?'stunned':a.d!=null?'attack':a.b?'guard':'snowAction';e.atk=a.d||0;e.hits=a.h||1;e.guardAmount=a.b||0;}}
function prepareAct5Action(r,e){if(!e.act5)return;e.archiveAction=archiveAction(r,e);e.archiveStunned=!!e.hunterStun||e.intent==='stunned';e.snowAction=e.archiveAction;e.atk=e.archiveAction.d||0;e.hits=e.archiveAction.h||1;e.guardAmount=e.archiveAction.b||0;}
function archiveExecute(r,e){const a=e.archiveAction||e.snowAction||{};if(a.d!=null&&a.b)e.block=(e.block||0)+a.b;if(a.reading)e.reading=true;if(a.s)e.str=(e.str||0)+a.s;if(a.heal)healHP(e,a.heal);if(a.growHeal)e.healGrowth=(e.healGrowth||0)+a.growHeal;if(a.healAll)for(const x of r.enemies)if(x.hp>0)healHP(x,a.healAll);if(a.support){const ally=r.enemies.find(x=>x.archiveId===a.supportTarget&&x.hp>0&&x!==e);if(ally)ally.str=(ally.str||0)+a.support;}if(a.summon){for(let i=0;i<a.count;i++){const key=r.archiveSummonBag.shift(),fresh=archiveFoe(key,r);fresh.max=fresh.hp=Math.ceil(ARCHIVE_FOES[key][1]*.6);fresh.str=a.extraStrength;fresh.block=a.extraBlock;fresh.collapseDamage=20;fresh.summonerId=e.archiveId;fresh.summonedTurn=r.turn;const deadIndex=r.enemies.findIndex(x=>x.hp<=0&&x.summonerId===e.archiveId);if(deadIndex>=0)r.enemies[deadIndex]=fresh;else r.enemies.push(fresh);}archiveBag(r);}if(a.clearReading)clearArchiveReading(e);}
function archiveDismiss(r,boss){for(const x of r.enemies)if(x!==boss&&x.hp>0&&x.summonerId===boss.archiveId){x.hp=0;x.archiveDismissed=true;x.archiveDeathResolved=true;}}
function onAct5Damage(r,e,lost,attack,beforeBlock){if(!e?.act5)return;if(attack&&beforeBlock>0&&e.block===0)clearArchiveReading(e);if(e.hp>0||e.archiveDeathResolved)return;e.archiveDeathResolved=true;if(e.act5Kind==='boss'){archiveDismiss(r,e);return;}if(e.collapseDamage&&!e.archiveDismissed){const boss=r.enemies.find(x=>x.archiveId===e.summonerId&&x.hp>0);if(boss)dealDamage(boss,e.collapseDamage,{ignoreBlock:true,hpLoss:true,damageKind:'破綻'});}}
const archiveDamageBase=dealDamage;dealDamage=function(...args){const lost=archiveDamageBase(...args);if(S.run?.act===5&&!S.run.enemyPhase)planArchive(S.run);return lost;};
const archiveChooseBase=choose;choose=function(type){const r=S.run,old=r?.mode;archiveChooseBase(type);if(r===S.run&&r?.act===5&&old!=='battle'&&r.mode==='battle'&&['fight','elite','boss'].includes(type)){r.enemies=archiveEncounter(r,type);target=0;healthVisuals.clear();planArchive(r);render();}};
