const archiveAbilityBase=enemyAbilities;enemyAbilities=function(e){if(!e.act5)return archiveAbilityBase(e);const a=[];if(e.act5Kind==='eater')a.push(['追憶','回復行動を実行するたび、回復量+3。現在の回復量：'+(6+(e.healGrowth||0))+'。']);if(e.act5Kind==='sage')a.push(['追憶','4番目の攻撃後、筋力3を得る。']);if(e.act5Kind==='boss')a.push(['召喚候補',archiveBag(S.run).slice(0,2).map(k=>ARCHIVE_FOES[k][0]).join(' ／ ')+'。読解なしなら先頭1体、読解ありなら2体（空き枠分）。'],['追憶','5番目の行動で筋力2を得る。'],['記録の召喚','召喚敵は最大2体。通常HPの60%で出現し、倒すと番人のHPを20減らす。']);if(e.collapseDamage)a.push(['破綻',keywords.破綻]);return a;};
const archiveStatusBase=enemyStatusHTML;enemyStatusHTML=function(e){let html=archiveStatusBase(e);if(e.act5&&e.reading){const extra=e.act5Kind==='book'?'次の攻撃を追加で1回行う。':e.act5Kind==='keeper'?'次の攻撃後に筋力4を得る。':'次の召喚は2体、各筋力2・ブロック10（空き枠分）。';html+='<span class="status-help" tabindex="0">読解<aside class="tooltip">'+keywords.読解+' 現在のブロック：'+(e.block||0)+'。'+extra+'</aside></span>';}return html;};
