const archiveIntentBase=intent;intent=function(e){if(!e.act5)return archiveIntentBase(e);if(e.hunterStun||e.intent==='stunned')return '<strong>⏸ スタン</strong>';const r=S.run,a=e.snowAction||{};let d=enemyAttack(e);if(e.weak)d=Math.floor(d*.7);d=hunterAttackDamage(r,r,d);const ally=r.enemies.find(x=>x.archiveId===a.supportTarget&&x.hp>0);return [a.d!=null?'<strong>⚔ '+d+(a.h>1?' × '+a.h:'')+'</strong>':'',a.b?'<strong>◇ '+a.b+'</strong>':'',a.reading?'<strong>読解</strong>':'',a.heal?'<strong>✚ '+a.heal+'</strong>':'',a.healAll?'<strong>✚ '+a.healAll+'</strong><small>敵全体</small>':'',a.support?'<strong>筋力 +'+(ally?a.support:0)+'</strong><small>'+(ally?ally.name:'対象なし')+'</small>':'',a.s?intentStatus('筋力',a.s):'',a.summon?'<strong>召喚 ×'+a.count+'</strong>'+(a.wasReading?'<small>各 筋力+2・ブロック10</small>':'')+'<small>候補：'+a.candidates.map(k=>ARCHIVE_FOES[k][0]).join(' ／ ')+'</small>':'',a.wait?'<strong>—</strong>':''].join('');};
const archiveBattleBase=battle;battle=function(){if(S.run?.act===5&&!S.run.enemyPhase)planArchive(S.run);const html=archiveBattleBase();return S.run?.act===5?html.replace(/<h2>[^<]*<\/h2>/,'<h2>'+(S.run.kind==='boss'?'記録の番人':S.run.kind==='elite'?'記憶の書庫の強敵':'記憶の書庫')+'</h2>'):html;};
